from typing import Dict, Tuple, Iterable, List

# Canonical definition of what counts as a produced artifact.
#
# Before this module existed, three components disagreed about the contents of a
# workspace:
#
#   * `sandbox_env.list_files()` skipped cache and virtualenv directories.
#   * `company.run()` applied a *separate* exclusion list, but only to the text it
#     appended to the CEO deliverable -- it returned the **unfiltered** bundle as
#     `run_output["workspace_files"]`.
#   * `sandbox_verifier` counted that unfiltered bundle when deciding the smoke
#     gate, and every downstream report counted it as "files authored on disk".
#
# The practical effect was that `.pytest_cache/CACHEDIR.TAG`, `__pycache__`
# entries, and paths where markdown formatting leaked into the filename (e.g.
# `src/agent_org/routing.py**`) were all scored as if an agent had authored them.
# Measured across Generations 5-10, **42-59% of every reported file count was
# junk or malformed**.
#
# Centralizing the rule here keeps the runtime, the verifier, and the analysis
# scripts honest and consistent.

EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

def is_generated_path(path: str) -> bool:
    """True if the path lives inside a machine-generated directory."""
    # Handle cases where the path itself is an excluded segment (e.g., ".pytest_cache")
    if path in EXCLUDED_DIR_SEGMENTS:
        return True

    # Paths in sandboxed environments are typically normalized to use '/'.
    # Using a fixed separator ensures deterministic behavior across platforms.
    parts = path.split('/')
    for part in parts:
        if part in EXCLUDED_DIR_SEGMENTS:
            return True
        for suffix in EXCLUDED_DIR_SUFFIXES:
            if part.endswith(suffix):
                return True
    return False

def is_malformed_path(path: str) -> bool:
    """True if markdown formatting or stray whitespace leaked into the filename.

    Agents emit path
    """
    if not path:
        return False # Empty path is not malformed in this sense

    # Check for leading/trailing whitespace
    if path != path.strip():
        return True

    # Check for common markdown formatting characters that might leak into filenames
    # and cause issues or look like malformed attempts.
    # This list is not exhaustive but covers common cases observed.
    forbidden_chars = ['*', '`', '[', ']', '(', ')', '#', '<', '>', '|', '?', '"', '\\', '/', '\n', '\r', '\t', ':']
    for char in forbidden_chars:
        if char in path:
            return True

    # Check for control characters (non-printable ASCII)
    # This might be overly aggressive for some systems, but for artifact paths,
    # we want clean, readable names.
    for char_code in range(0, 32): # ASCII control characters
        if chr(char_code) in path:
            return True
    for char_code in range(127, 160): # DEL and C1 control characters
        if chr(char_code) in path:
            return True

    return False

# This is a heuristic to detect paths that are likely not intended to be "authored"
# by an agent, but rather are part of the environment or generated by tools.
# This includes things like Python bytecode, virtual environment files, git metadata, etc.
def is_ignored_path(path: str) -> bool:
    """True if the path should be ignored for artifact counting."""
    return is_generated_path(path) or is_malformed_path(path)

def filter_workspace_artifacts(workspace_files: Dict[str, str]) -> Dict[str, str]:
    """Filters out generated and malformed paths from the workspace files."""
    filtered_files = {}
    for path, content in workspace_files.items():
        if not is_ignored_path(path):
            filtered_files[path] = content
    return filtered_files

def calculate_authored_lines(workspace_files: Dict[str, str]) -> int:
    """Calculates the total number of lines in non-ignored files."""
    total_lines = 0
    for path, content in workspace_files.items():
        if not is_ignored_path(path):
            total_lines += content.count('\n') + (1 if content and not content.endswith('\n') else 0)
    return total_lines

def calculate_authored_files(workspace_files: Dict[str, str]) -> int:
    """Calculates the total number of non-ignored files."""
    count = 0
    for path in workspace_files.keys():
        if not is_ignored_path(path):
            count += 1
    return count

def get_top_level_directories(paths: Iterable[str]) -> List[str]:
    """Extracts unique top-level directory names from a list of paths."""
    top_level_dirs = set()
    for path in paths:
        if '/' in path:
            top_level_dirs.add(path.split('/')[0])
        else:
            # If it's a file at the root, its "top-level directory" is effectively its own name
            # This might need refinement based on exact requirements, but for now,
            # we'll treat root files as their own top-level entries.
            top_level_dirs.add(path)
    return sorted(list(top_level_dirs))

def get_file_extension(path: str) -> str:
    """Extracts the file extension from a path."""
    parts = path.split('.')
    if len(parts) > 1 and parts[-1]:
        return parts[-1]
    return ""

def get_file_type_counts(workspace_files: Dict[str, str]) -> Dict[str, int]:
    """Counts files by extension, ignoring generated/malformed paths."""
    file_type_counts: Dict[str, int] = {}
    for path in workspace_files.keys():
        if not is_ignored_path(path):
            ext = get_file_extension(path)
            if ext:
                file_type_counts[ext] = file_type_counts.get(ext, 0) + 1
            else:
                file_type_counts['no_extension'] = file_type_counts.get('no_extension', 0) + 1
    return file_type_counts

def get_average_line_length(workspace_files: Dict[str, str]) -> float:
    """Calculates the average line length across all non-ignored files."""
    total_chars = 0
    total_lines = 0
    for path, content in workspace_files.items():
        if not is_ignored_path(path):
            lines = content.splitlines()
            for line in lines:
                total_chars += len(line)
            total_lines += len(lines)
    return total_chars / total_lines if total_lines > 0 else 0.0

def get_longest_line(workspace_files: Dict[str, str]) -> Tuple[str, int, str]:
    """Finds the longest line in non-ignored files, returning (path, line_number, line_content)."""
    longest_line_content = ""
    longest_line_path = ""
    longest_line_num = -1

    for path, content in workspace_files.items():
        if not is_ignored_path(path):
            lines = content.splitlines()
            for i, line in enumerate(lines):
                if len(line) > len(longest_line_content):
                    longest_line_content = line
                    longest_line_path = path
                    longest_line_num = i + 1 # 1-indexed

    return (longest_line_path, longest_line_num, longest_line_content)

def get_most_common_words(workspace_files: Dict[str, str], n: int = 10) -> List[Tuple[str, int]]:
    """Finds the N most common words across all non-ignored files."""
    from collections import Counter
    import re

    all_words = []
    for path, content in workspace_files.items():
        if not is_ignored_path(path):
            # Use a regex to find words (alphanumeric sequences)
            words = re.findall(r'\b\w+\b', content.lower())
            all_words.extend(words)

    word_counts = Counter(all_words)
    return word_counts.most_common(n)
